def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = 7

    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != bg]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]

    def segments(size, separators):
        result = []
        start = 0
        for p in separators:
            if start < p:
                result.append((start, p))
            start = p + 1
        if start < size:
            result.append((start, size))
        return result

    row_blocks = segments(h, sep_rows)
    col_blocks = segments(w, sep_cols)

    out = [row[:] for row in grid]
    template = None
    for r0, r1 in row_blocks:
        for c0, c1 in col_blocks:
            cells = [
                (r - r0, c - c0, grid[r][c])
                for r in range(r0, r1)
                for c in range(c0, c1)
                if grid[r][c] != bg
            ]
            if cells:
                template = cells
                break
        if template:
            break

    if template:
        for r0, r1 in row_blocks:
            for c0, c1 in col_blocks:
                for dr, dc, color in template:
                    if r0 + dr < r1 and c0 + dc < c1:
                        out[r0 + dr][c0 + dc] = color

    return out
